16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.Digits;
22	import jakarta.validation.constraints.Email;
23	import jakarta.validation.constraints.NotEmpty;
24	import jakarta.validation.constraints.Pattern;
25	
26	import java.time.LocalDate;
27	import java.util.*;
28	
29	/**
30	 * Simple JavaBean domain object representing an owner.
31	 *
32	 * @author Ken Krebs
33	 * @author Juergen Hoeller
34	 * @author Sam Brannen
35	 * @author Michael Isvy
36	 */
37	@Entity
38	@Table(name = "owners")
39	public class Owner extends Person {
40	    @Column(name = "address")
41	    @NotEmpty
42	    private String address;
43	
44	    @Column(name = "city")
45	    @NotEmpty
46	    private String city;
47	
48	    @Column(name = "telephone")
49	    @NotEmpty
50	    @Digits(fraction = 0, integer = 10)
51	    @Pattern(regexp = "^[0-9]{10}$", message = "Phone number must be exactly 10 digits")
52	    private String telephone;
53	
54	    @Column(name = "email")
55	    @Email
56	    private String email;
57	
58	    @Column(name = "registration_date", columnDefinition = "DATE")
59	    private LocalDate registrationDate;
60	
61	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
62	    private Set<Pet> pets;
63	
64	    public String getAddress() {
65	        return this.address;
66	    }
67	
68	    public void setAddress(String address) {
69	        this.address = address;
70	    }
71	
72	    public String getCity() {
73	        return this.city;
74	    }
75	
76	    public void setCity(String city) {
77	        this.city = city;
78	    }
79	
80	    public String getTelephone() {
81	        return this.telephone;
82	    }
83	
84	    public void setTelephone(String telephone) {
85	        this.telephone = telephone;
86	    }
87	
88	    public String getEmail() {
89	        return this.email;
90	    }
91	
92	    public void setEmail(String email) {
93	        this.email = email;
94	    }
95	
96	    public LocalDate getRegistrationDate() {
97	        return this.registrationDate;
98	    }
99	
100	    public void setRegistrationDate(LocalDate registrationDate) {
101	        this.registrationDate = registrationDate;
102	    }
103	
104	    protected Set<Pet> getPetsInternal() {
105	        if (this.pets == null) {
106	            this.pets = new HashSet<>();
107	        }
108	        return this.pets;
109	    }
110	
111	    protected void setPetsInternal(Set<Pet> pets) {
112	        this.pets = pets;
113	    }
114	
115	    public List<Pet> getPets() {
116	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
117	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
118	        return Collections.unmodifiableList(sortedPets);
119	    }
120	
121	    public void setPets(List<Pet> pets) {
122	        this.pets = new HashSet<>(pets);
123	    }
124	
125	    public void addPet(Pet pet) {
126	        getPetsInternal().add(pet);
127	        pet.setOwner(this);
128	    }
129	
130	    /**
131	     * Return the Pet with the given name, or null if none found for this Owner.
132	     *
133	     * @param name to test
134	     * @return true if pet name is already in use
135	     */
136	    public Pet getPet(String name) {
137	        return getPet(name, false);
138	    }
139	
140	    /**
141	     * Return the Pet with the given name, or null if none found for this Owner.
142	     *
143	     * @param name to test
144	     * @return true if pet name is already in use
145	     */
146	    public Pet getPet(String name, boolean ignoreNew) {
147	        name = name.toLowerCase();
148	        for (Pet pet : getPetsInternal()) {
149	            if (!ignoreNew || !pet.isNew()) {
150	                String compName = pet.getName();
151	                compName = compName.toLowerCase();
152	                if (compName.equals(name)) {
153	                    return pet;
154	                }
155	            }
156	        }
157	        return null;
158	    }
159	
160	    public Pet getPet(Integer petId) {
161	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
162	    }
163	
164	    @Override
165	    public String toString() {
166	        return new ToStringCreator(this)
167	
168	            .append("id", this.getId())
169	            .append("new", this.isNew())
170	            .append("lastName", this.getLastName())
171	            .append("firstName", this.getFirstName())
172	            .append("address", this.address)
173	            .append("city", this.city)
174	            .append("telephone", this.telephone)
175	            .append("email", this.email)
176	            .append("registrationDate", this.registrationDate)
177	            .toString();
178	    }
179	}
