6	/**
7	 * Normalizes a create request's telephone by removing every non-digit character, then
8	 * requires exactly ten digits, storing the normalized value back on the body so later
9	 * steps persist and return it. Runs after {@link ValidateOwnerFields} has confirmed the
10	 * field is present and published the body; mutates that same instance in place.
11	 */
12	public class NormalizeOwnerTelephone {
13	
14	    private static final int REQUIRED_DIGITS = 10;
15	
16	    public void service(@Val OwnerFieldsDto request) throws InvalidTelephoneException {
17	        String telephone = request.getTelephone();
18	        String digits = Telephones.normalize(telephone);
19	        if (digits.length() != REQUIRED_DIGITS) {
20	            throw new InvalidTelephoneException(telephone);
21	        }
22	        request.setTelephone(digits);
23	    }
24	}
