1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
6	import org.springframework.samples.petclinic.repository.OwnerRepository;
7	
8	/**
9	 * Rejects a create request whose normalized telephone is already used by any existing
10	 * owner. Runs after {@link NormalizeOwnerTelephone} has reduced the body's telephone to
11	 * its digits, comparing it against every stored owner's normalized number so numbers that
12	 * differ only in separators are still treated as duplicates.
13	 */
14	public class EnsureUniqueTelephone {
15	
16	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
17	            throws DuplicateTelephoneException {
18	        String telephone = Telephones.normalize(request.getTelephone());
19	        for (Owner owner : ownerRepository.findAll()) {
20	            if (telephone.equals(Telephones.normalize(owner.getTelephone()))) {
21	                throw new DuplicateTelephoneException(telephone);
22	            }
23	        }
24	    }
25	}
