1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	/**
4	 * Shared telephone normalization: strips every non-digit character so equivalent numbers
5	 * written with different separators compare equal. Used both to normalize a create
6	 * request before it is persisted and to compare it against existing owners' numbers.
7	 */
8	final class Telephones {
9	
10	    private Telephones() {
11	    }
12	
13	    /** Returns {@code telephone} reduced to its digits ("" when {@code null}). */
14	    static String normalize(String telephone) {
15	        return telephone == null ? "" : telephone.replaceAll("\\D", "");
16	    }
17	}
